'use strict';
const retailBundleCanSell=()=>canWrite()&&['admin','sales','service'].includes(state.user.role);
const retailBundleCanConfigure=()=>canWrite()&&['admin','manager'].includes(state.user.role);
const retailBundleLabel=r=>`${r.name} · ${r.code} · 第${r.rule_version}版`;
function clearRetailBundlesSession(){delete state.retailBundleRules;delete state.retailBundleLineHtml;}
function retailBundleFacts(r,sets=1){return `<p><strong>${E(retailBundleLabel(r))}</strong> · 本次 ${number(sets)} 套</p><p>每套成交 ${money(r.price_cents_per_set)} 元；本次合计 <strong>${money(r.price_cents_per_set*sets)} 元</strong>。</p>`+r.components.map(c=>`<div class="taskitem"><div class="description"><strong>${E(c.sku)} · ${E(c.name)}</strong><p>数量 ${number(c.quantity_milli_per_set*sets/1000)} ${E(c.unit)} · 商品套餐分摊 ${money(c.goods_cents_per_set*sets)} 元</p><p>${c.work_item_id?`安装：${E(c.work_name)} · 安装套餐分摊 ${money(c.installation_cents_per_set*sets)} 元`:'无需安装'}</p></div></div>`).join('')+`<p>${E(r.mandatory_terms)}</p><p>本版本补充条款：${E(r.refund_terms)}</p>`;}
async function retailBundlesPage(){
 if(state.store==='all')return heading('精品销售套餐')+storeNotice();
 const d=await api('/api/retail-bundles/rules');state.retailBundleRules=d.items;
 const current=d.items.filter(r=>r.is_latest&&r.enabled);
 return heading('精品销售套餐','',b('open','精品订单','data-route="retail"')+(retailBundleCanConfigure()?b('open','配置套餐规则','data-route="retail-bundle-rules"'):''))+storeNotice()+(current.length?current.map(r=>panel(r.name,`<p>销售期间 ${E(r.sale_starts_on)} 至 ${E(r.sale_ends_on)}</p>`+retailBundleFacts(r)+(retailBundleCanSell()?b('retail-bundle-sale','核对客户与套数',`data-id="${r.id}"`,'primary'):''))).join(''):panel('尚无启用套餐','<p>店长可发布包含商品、安装、参考金额、成交价及明确退货条款的版本，默认关闭，确认后启用新版本。</p>'));
}
async function retailBundleRulesPage(){
 if(state.store==='all')return heading('精品套餐配置')+storeNotice();
 const d=await api('/api/retail-bundles/rules');state.retailBundleRules=d.items;
 return heading('精品套餐配置','',b('open','返回套餐','data-route="retail-bundles"')+(retailBundleCanConfigure()?b('retail-bundle-rule','发布新套餐','','primary'):''))+d.items.map(r=>panel(retailBundleLabel(r),`<p>${r.is_latest?'当前版本':'历史版本'} · ${r.enabled?'本版本已启用':'本版本未启用'} · ${E(r.sale_starts_on)} 至 ${E(r.sale_ends_on)}</p>`+retailBundleFacts(r)+(retailBundleCanConfigure()&&r.is_latest?b('retail-bundle-rule','复制并发布下一版本',`data-id="${r.id}"`):''))).join('');
}
async function retailBundleSale(id){
 const rule=state.retailBundleRules.find(r=>r.id===id);if(!rule)throw new Error('套餐列表已变化，请刷新。');
 const customers=await retailAll('/api/flow/master/customers?page_size=100');if(!customers.length)throw new Error('请先建立本人可办理的本店客户档案。');
 modal('选择客户和套餐套数',`<form><label>本店客户<select name="customer" required>${customers.map(c=>`<option value="${c.id}">${E(c.name)} · ${E(c.phone||'')}</option>`).join('')}</select></label><label>购买套数<input name="sets" type="number" min="1" max="10000" step="1" value="1" required></label><p>下一步展示本次冻结组成、分摊金额和退货条款；提交时后台再次检查可用库存。</p><div class="formerror" role="alert"></div><div class="modalfoot"><button type="submit" class="primary">核对本次清单</button></div></form>`,async form=>{
  const customer_id=Number(form.elements.customer.value),sets=Number(form.elements.sets.value);
  if(!Number.isSafeInteger(sets)||sets<1)throw new Error('套数须为正整数。');
  const current=await api(`/api/retail-bundles/rules/${id}/preview?sets=${sets}`),request_id=requestKey();
  modal('确认套餐分摊与退货规则',`<form>${await memberPriceField(null,customer_id)}${retailBundleFacts(current,sets)}<p>本店当前可用商品最多支持 ${number(current.available_sets)} 套；占用在提交成功后生效。</p><label><input name="accepted" type="checkbox" required> 已向客户说明本次组成和冻结退货规则</label><p>提交后由主管核价，再请客户确认。</p><div class="formerror" role="alert"></div><div class="modalfoot"><button type="submit" class="primary">冻结本单并申请审批</button></div></form>`,async confirm=>{
   const row=await api('/api/retail-bundles/sales',{method:'POST',body:{request_id,rule_id:id,rule_version:current.rule_version,sets,customer_id,...memberPricePayload(confirm),terms_accepted:confirm.elements.accepted.checked}});closeModal();go('retail/'+row.id);
  });
 });
}
async function retailBundleRule(id){
 const source=state.retailBundleRules?.find(r=>r.id===id),[items,works]=await Promise.all([retailAll('/api/retail/items'),retailAll('/api/retail/installations')]);
 if(!items.length)throw new Error('请先配置本店启用的商品目录。');
 const line=c=>`<div class="panelbody" data-retail-bundle-line><label>商品<select name="item" required><option value="">请选择本店商品</option>${items.map(x=>`<option value="${x.id}" ${c?.item_id===x.id?'selected':''}>${E(x.sku)} · ${E(x.name)} · ${E(x.unit)}</option>`).join('')}</select></label><div class="formgrid"><label>每套此商品数量<input name="quantity" inputmode="decimal" value="${c?number(c.quantity_milli_per_set/1000).replaceAll(',',''):'1.000'}" required></label><label>每套此商品参考金额（元）<input name="goods" inputmode="decimal" value="${c?(c.goods_reference_cents/100).toFixed(2):''}" required></label></div><label>对应安装项目<select name="work"><option value="">无需安装</option>${works.map(x=>`<option value="${x.id}" ${c?.work_item_id===x.id?'selected':''}>${E(x.code)} · ${E(x.name)}</option>`).join('')}</select></label><label>每套此安装参考金额（元）<input name="installation" inputmode="decimal" value="${c?(c.installation_reference_cents/100).toFixed(2):'0.00'}" required></label>${b('retail-bundle-remove','删除此组成')}</div>`;
 state.retailBundleLineHtml=line();const request_id=requestKey();
 modal(source?'发布精品套餐下一版本':'发布精品套餐',`<form><label>套餐代码<input name="code" value="${E(source?.code||'')}" ${source?'readonly':''} pattern="[A-Za-z0-9_-]+" maxlength="40" required></label><label>套餐名称<input name="name" value="${E(source?.name||'')}" maxlength="120" required></label><p>参考金额是每一整套内此组件的总参考金额，不是商品单价。系统按商品与安装参考金额占比分摊成交价，同余分按以下组成顺序分配；每套分摊冻结后再乘购买套数。同一商品只列一次。</p><div id="retail-bundle-lines">${source?source.components.map(line).join(''):line()}</div>${b('retail-bundle-add','增加组成')}<label>每套实际成交金额（元）<input name="price" inputmode="decimal" value="${source?(source.price_cents_per_set/100).toFixed(2):''}" required></label><div class="formgrid"><label>销售开始日期<input name="starts" type="date" value="${E(source?.sale_starts_on||relativeDay(0))}" required></label><label>销售结束日期<input name="ends" type="date" value="${E(source?.sale_ends_on||relativeDay(30))}" required></label></div><p>退货按原组件分摊，不重新定价剩余商品；已履约安装费保留、未施工安装费随验收退货减免。</p><label>发行前明确的补充条款<textarea name="terms" minlength="10" maxlength="1500" required>${E(source?.refund_terms||'')}</textarea></label><label><input name="enabled" type="checkbox"> 明确启用此新版本供之后开单</label><p>默认不启用。发布下一版后，旧版停止用于新开单，已有订单继续按原版办理。</p><div class="formerror" role="alert"></div><div class="modalfoot"><button type="submit" class="primary">发布冻结版本</button></div></form>`,async form=>{
  const components=[...form.querySelectorAll('[data-retail-bundle-line]')].map(el=>({item_id:Number(el.querySelector('[name=item]').value),quantity_milli_per_set:retailScaled(el.querySelector('[name=quantity]').value,3),goods_reference_cents:retailScaled(el.querySelector('[name=goods]').value,2),work_item_id:Number(el.querySelector('[name=work]').value)||null,installation_reference_cents:retailScaled(el.querySelector('[name=installation]').value,2)}));
  await api('/api/retail-bundles/rules',{method:'POST',body:{request_id,base_version:source?.rule_version||0,values:{code:form.elements.code.value,name:form.elements.name.value,enabled:form.elements.enabled.checked,sale_starts_on:form.elements.starts.value,sale_ends_on:form.elements.ends.value,price_cents_per_set:retailScaled(form.elements.price.value,2),refund_terms:form.elements.terms.value,components}}});closeModal();await render();toast('套餐版本已冻结保存');
 });
}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-act]');if(!el?.dataset.act.startsWith('retail-bundle-'))return;try{switch(el.dataset.act){case'retail-bundle-sale':await retailBundleSale(Number(el.dataset.id));break;case'retail-bundle-rule':await retailBundleRule(Number(el.dataset.id)||undefined);break;case'retail-bundle-add':$('#retail-bundle-lines').insertAdjacentHTML('beforeend',state.retailBundleLineHtml);break;case'retail-bundle-remove':if(document.querySelectorAll('[data-retail-bundle-line]').length<=1)throw new Error('至少保留一个商品组成。');el.closest('[data-retail-bundle-line]').remove();break;}}catch(error){toast(error.message,true);}});
